def solve(g):
    R,C=len(g),len(g[0])
    out=[row[:] for row in g]
    start=[(r,c) for r in range(R) for c in range(C) if g[r][c]==2][0]
    r0,c0=start
    dists={'down':R-1-r0,'up':r0,'right':C-1-c0,'left':c0}
    d=max(dists,key=dists.get)
    DL={'down':(1,0),'up':(-1,0),'right':(0,1),'left':(0,-1)}
    def is8(r,c): return 0<=r<R and 0<=c<C and g[r][c]==8
    def turn_dir(r,c,dr,dc):
        # horizontal motion -> look for gap BELOW; vertical motion -> gap to the RIGHT
        if dr==0: sr,sc=1,0
        else: sr,sc=0,1
        ar,ac=r+sr,c+sc
        if 0<=ar<R and 0<=ac<C and g[ar][ac]==0:
            if sr==0:
                ok=is8(ar-1,ac) and is8(ar+1,ac) and (is8(ar-2,ac) or is8(ar+2,ac))
            else:
                ok=is8(ar,ac-1) and is8(ar,ac+1) and (is8(ar,ac-2) or is8(ar,ac+2))
            if ok: return (sr,sc)
        return None
    beams=[(r0,c0,DL[d])]
    while beams:
        r,c,(dr,dc)=beams.pop()
        while True:
            nr,nc=r+dr,c+dc
            if not(0<=nr<R and 0<=nc<C): break
            if g[nr][nc]==8:
                out[r][c]=2
                nds=[(1,0),(-1,0)] if dr==0 else [(0,1),(0,-1)]
                for nd in nds: beams.append((r,c,nd))
                break
            r,c=nr,nc
            out[r][c]=2
            td=turn_dir(r,c,dr,dc)
            if td:
                beams.append((r,c,td))
                break
    return out
